ddl:
create policy "Allow authenticated users to update games" on public.games as permissive for update to authenticated
  using (true)
  with check (true);

create policy "Users can update own profile" on public.profiles as permissive for update to public
  using ((auth.uid() = id))
  with check ((auth.uid() = id));

create policy weeks_update_admin on public.weeks as permissive for update to authenticated
  using (is_admin())
  with check (is_admin());

CREATE OR REPLACE FUNCTION public.admin_create_invite(p_email text DEFAULT NULL::text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS invites
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_invite     public.invites;
  v_code       text;
  v_expires_at timestamptz;
  v_email      text := nullif(lower(trim(coalesce(p_email, ''))), '');
begin
  if not public.is_admin() then
    raise exception 'admin_create_invite: admins only';
  end if;

  if v_email is not null and v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    raise exception 'admin_create_invite: % is not an email address', v_email;
  end if;

  if p_expires_at is not null and p_expires_at <= now() then
    raise exception 'admin_create_invite: expiry is already in the past';
  end if;

  -- Codes are UNCAPPED: any number of people can redeem one until it expires
  -- or is revoked. That is the point -- one key to the group email beats twelve
  -- codes and twelve messages, and it is what makes signup genuinely self-serve
  -- rather than making the admin the bottleneck.
  --
  -- Which is exactly why it must not be open-ended. An expiry is defaulted
  -- rather than demanded, so a hurried admin cannot mint a permanent door by
  -- omission. Pass one explicitly to override -- and for the pool's main code,
  -- DO: 14 days from the season opener dies in the middle of October.
  v_expires_at := coalesce(p_expires_at, now() + interval '14 days');

  -- Binding to an address is what makes a code PERSONAL rather than shared:
  -- uncapped means nothing when only one person may use it. So the two shapes
  -- are the same mechanism -- leave the email off for the group key, set it for
  -- a single named late joiner.
  --
  -- Refuse to invite somebody who is already in. Cheap, and it stops a second
  -- code being minted for a member who simply forgot their password.
  if v_email is not null and exists (
    select 1 from public.profiles where lower(email) = v_email
  ) then
    raise exception 'admin_create_invite: % is already a member', v_email;
  end if;

  -- No retry loop. At 48 bits the first collision is expected somewhere around
  -- sixteen million codes and this pool will mint dozens, so catching
  -- unique_violation would only add a guard that cannot fire.
  v_code := public.generate_invite_code();

  insert into public.invites (code, email, created_by, expires_at)
  values (v_code, v_email, auth.uid(), v_expires_at)
  returning * into v_invite;

  return v_invite;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_revoke_invite(p_code text)
 RETURNS invites
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_invite public.invites;
begin
  if not public.is_admin() then
    raise exception 'admin_revoke_invite: admins only';
  end if;

  update public.invites
     set revoked_at = now()
   where code = public.normalise_invite_code(p_code)
     and revoked_at is null
  returning * into v_invite;

  if v_invite.code is null then
    raise exception 'admin_revoke_invite: no such code, or it is already revoked';
  end if;

  return v_invite;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_game_score_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if current_user not in ('anon', 'authenticated') then
    return new;
  end if;

  if tg_op = 'INSERT' then
    new.home_score := null;
    new.away_score := null;
    new.status := 'SCHEDULED';
    return new;
  end if;

  raise exception 'games are scored by the league sync and cannot be changed here'
    using errcode = 'insufficient_privilege';
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_pick_score_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if current_user not in ('anon', 'authenticated') then
    return new;
  end if;

  if tg_op = 'INSERT' then
    new.points_earned := 0;
    new.result := 'PENDING';
    return new;
  end if;

  if new.points_earned is distinct from old.points_earned then
    raise exception 'picks.points_earned is set by scoring and cannot be changed here'
      using errcode = 'insufficient_privilege';
  end if;

  if new.result is distinct from old.result then
    raise exception 'picks.result is set by scoring and cannot be changed here'
      using errcode = 'insufficient_privilege';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_profile_column_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if current_user not in ('anon', 'authenticated') then
    return new;
  end if;

  if new.id is distinct from old.id then
    raise exception 'profiles.id cannot be changed'
      using errcode = 'insufficient_privilege';
  end if;

  if new.role is distinct from old.role then
    raise exception 'profiles.role can only be changed by a league administrator'
      using errcode = 'insufficient_privilege';
  end if;

  if new.email is distinct from old.email then
    raise exception 'profiles.email is managed by authentication and cannot be changed here'
      using errcode = 'insufficient_privilege';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_week_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  derived date;
begin
  if current_user not in ('anon', 'authenticated') then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.id !~ '^week-\d{4}-\d{2}-\d{2}$' then
      raise exception 'weeks.id must look like week-YYYY-MM-DD, got %', new.id
        using errcode = 'invalid_parameter_value';
    end if;

    derived := substring(new.id from 6)::date;

    if extract(isodow from derived) <> 6 then
      raise exception 'weeks.id must name a Saturday, got % (%)',
        derived, to_char(derived, 'Day')
        using errcode = 'invalid_parameter_value';
    end if;

    -- The deadline comes from the id, never from what the client sent.
    new.saturday_date := derived;
    new.status := 'OPEN';
    return new;
  end if;

  if new.id is distinct from old.id
     or new.saturday_date is distinct from old.saturday_date
     or new.week_number is distinct from old.week_number then
    raise exception 'a week''s date and number are fixed once it exists; only status may change'
      using errcode = 'insufficient_privilege';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.redeem_invite(p_code text, p_name text)
 RETURNS profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_email   text;
  v_name    text := nullif(trim(coalesce(p_name, '')), '');
  v_code    text := public.normalise_invite_code(p_code);
  v_invite  public.invites;
  v_profile public.profiles;
begin
  if v_user_id is null then
    raise exception 'redeem_invite: not authenticated';
  end if;

  if v_name is null then
    raise exception 'redeem_invite: a name is required';
  end if;

  if exists (select 1 from public.profiles where id = v_user_id) then
    raise exception 'redeem_invite: you are already a member';
  end if;

  -- The address comes from auth.users, never from the client. An email-bound
  -- invite is only worth something if the binding cannot be asserted by the
  -- person redeeming it.
  select lower(email) into v_email from auth.users where id = v_user_id;

  -- auth.users.email is nullable -- phone signup, some OAuth providers. Without
  -- this guard the binding check below cannot do its job: a naive `<>` against
  -- NULL evaluates to NULL rather than true, so it never fires and a bound code
  -- becomes redeemable by the wrong person. The only thing that would catch it
  -- is profiles.email being NOT NULL and failing one statement later, which is
  -- luck, not a rule.
  if v_email is null then
    raise exception 'redeem_invite: your account has no email address';
  end if;

  -- Locked, though nothing about the code changes here. Two people redeeming
  -- the same group key at the same instant is the ordinary case and both should
  -- succeed; the lock is what serialises the expiry and revocation checks
  -- against an admin revoking mid-redemption.
  select * into v_invite
    from public.invites
   where code = v_code
     for update;

  if v_invite.code is null then
    raise exception 'redeem_invite: that invite code is not valid';
  end if;

  -- No "already used" check: a code is reusable by design. What stops one
  -- PERSON using it twice is the profile check above and unique (user_id) on
  -- invite_claims, not the state of the code.
  if v_invite.revoked_at is not null then
    raise exception 'redeem_invite: that invite is no longer open';
  end if;

  if v_invite.expires_at is not null and v_invite.expires_at <= now() then
    raise exception 'redeem_invite: that invite has expired';
  end if;

  -- `is distinct from` rather than `<>`, so a NULL on either side cannot
  -- silently skip the check.
  if v_invite.email is not null and v_invite.email is distinct from v_email then
    -- Deliberately does not name the address the code is for; that would turn
    -- a leaked code into a way of harvesting who was invited.
    raise exception 'redeem_invite: that invite was issued to a different email address';
  end if;

  -- `role` is not settable here by anyone. A redeemed invite always produces a
  -- member; promoting somebody is a separate, deliberate act. `avatar` is left
  -- null -- members set it from Settings, and every view falls back to initials.
  insert into public.profiles (id, email, name)
  values (v_user_id, v_email, v_name)
  returning * into v_profile;

  insert into public.invite_claims (code, user_id)
  values (v_invite.code, v_user_id);

  return v_profile;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.save_picks(p_user_id uuid, p_week_id text, p_picks jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  -- Shape checks. The client checks these too, for a faster and friendlier
  -- error; the console does not, and this is the copy that is not optional.
  if jsonb_typeof(p_picks) is distinct from 'array' then
    raise exception 'Picks must be an array';
  end if;

  if jsonb_array_length(p_picks) <> 5 then
    raise exception 'Must submit exactly 5 picks';
  end if;

  if (
    select count(distinct (e->>'confidence')::int)
      from jsonb_array_elements(p_picks) e
     where (e->>'confidence')::int between 1 and 5
  ) <> 5 then
    raise exception 'Confidence values must be unique and between 1 and 5';
  end if;

  -- Report a locked week in words. Without this the RLS policy still refuses
  -- the write, but as an opaque "violates row-level security policy". Same
  -- transaction as the statements below, so it cannot disagree with them.
  if picks_revealed(p_week_id) then
    raise exception 'Picks are locked. Deadline has passed.';
  end if;

  -- The two statements this function exists for. RLS applies to both.
  delete from public.picks
   where user_id = p_user_id
     and week_id = p_week_id;

  insert into public.picks (user_id, week_id, game_id, selected_team_id, confidence)
  select p_user_id,
         p_week_id,
         e->>'gameId',
         e->>'selectedTeamId',
         (e->>'confidence')::int
    from jsonb_array_elements(p_picks) e;
end;
$function$
;
